(function(w,d){"use strict";var jo=w.joinchat_obj;if(typeof jo!=="object"||!jo)return;var cfg=w.joinchat_random_phone||{},assigned=null,cb={};function g(k){try{return w.localStorage.getItem(k)}catch(e){return null}}function s(k,v){try{w.localStorage.setItem(k,v)}catch(e){}}function sh(a){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a}function pa(p){if(p.length===1)return p[0];var k="joinchat_rp_bag_"+p.join("_"),b=cb[k];if(!b||!b.length){try{b=JSON.parse(g(k)||"[]")}catch(e){b=[]}if(!b.length)b=sh(p.slice())}var ph=b.shift();cb[k]=b;s(k,JSON.stringify(b));return ph}function rp(p){if(Array.isArray(p))return p.length?pa(p):p;var def=jo.settings&&jo.settings.telephone;if(!p||p===def)return assigned||def||p;return p}var og=jo.get_wa_link;jo.get_wa_link=function(p,m,ww){return og.call(this,rp(p),m,ww)};var oo=jo.open_whatsapp;jo.open_whatsapp=function(p,m,t){return oo.call(this,rp(p),m,t)};function la(){if(!cfg.signature||!cfg.url)return;var st=g("joinchat_rp_assigned");if(st){try{var da=JSON.parse(st);if(da&&da.sig===cfg.signature&&da.phone){assigned=da.phone;return}}catch(e){}}var body="action="+encodeURIComponent(cfg.action||"joinchat_random_phone")+"&signature="+encodeURIComponent(cfg.signature)+(cfg.nonce?"&nonce="+encodeURIComponent(cfg.nonce):"");fetch(cfg.url,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded; charset=UTF-8"},body:body,credentials:"same-origin"}).then(function(r){return r.json()}).then(function(res){if(res&&res.success&&res.data&&res.data.phone){assigned=res.data.phone;s("joinchat_rp_assigned",JSON.stringify({sig:cfg.signature,phone:assigned}))}}).catch(function(){})}la()})(window,document);
